 function addRule(phrase,label){phrase=phrase.trim().replace(/\s+/g,' ');if(!phrase)return;const i=rules.findIndex(r=>r.phrase.toLocaleLowerCase('ru')===phrase.toLocaleLowerCase('ru'));if(i>=0&&rules[i].label===label){status(`Правило «${phrase} → ${label}» уже существует.`);return;}white=white.filter(w=>w.toLocaleLowerCase('ru')!==phrase.toLocaleLowerCase('ru'));if(i>=0)rules[i]={phrase,label};else rules.push({phrase,label});status(`Правило «${phrase} → ${label}» сохранено.`);}
 function addWhite(phrase){phrase=phrase.trim().replace(/\s+/g,' ');if(!phrase)return;rules=rules.filter(r=>r.phrase.toLocaleLowerCase('ru')!==phrase.toLocaleLowerCase('ru'));if(white.some(w=>w.toLocaleLowerCase('ru')===phrase.toLocaleLowerCase('ru'))){status(`«${phrase}» уже есть в белом списке.`);return;}white.push(phrase);status(`«${phrase}» добавлено в белый список.`);}
