 document.querySelectorAll('button').forEach(b=>{if(b.id&&['mockAddRule','mockAddWhite','mockClose','mockCancel','mockSave','hideHint','keepHint','themeToggle'].includes(b.id))return;if(!b.onclick)b.addEventListener('click',()=>status(`Прототип: «${b.textContent.trim()}» показано без изменения файлов.`));});
